// Projektideen „Lead gesucht“ (E-39, Entscheidung neVs 2026-11-07): swarvex schlägt Vorhaben vor, die zum Schwarm passen
// (prüfbar, gut zu zerlegen, mit Bereichen für Bereichs-Leads). Wer eine Idee übernimmt („Als Lead übernehmen“), legt das
// Projekt über den Assistenten an, wird sein Visionär und Lead und bekommt den Teilen-Link. Der Entwurf hier ist nur der
// Anfang: Vision, Ziel, Stack und Lizenzen ändert die Person beim Anlegen und danach. Jede Idee wird einmal übernommen
// (projekte.idee); ein Entwurf, der 14 Tage nicht veröffentlicht wird, gibt sie wieder frei.
// Regeln gelten wie für jedes Projekt: Clean Room ohne Code des Originals und ohne Umgehen von Schutzmaßnahmen,
// Weiterführung nur archivierter oder übergebener Projekte, Spiele als eigene Entwürfe.
import type { Db } from "./db.ts";

type Text = { name: string; kurz: string; ziel: string; warum: string; schwarm_vorteil: string; vision: string };
export type Idee = {
  idee: string; art: string; verfahren: "standard" | "clean_room" | "continuation"; engine: string;
  lizenz_code: string; lizenz_assets: string; bereiche: string[]; quellen: string[];
  original?: { name: string; target: string; depth: "observe" | "inspect" };
  upstream?: { repo: string; license: string; status: string };
  forschung?: { kind: string; source: string; success: string };
  // Schon begonnen: ein öffentliches Repo als Startpunkt (wer übernimmt, forkt es) und was darin schon steht
  start?: { repo: string; de: string; en: string };
  de: Text; en: Text;
};

const vision = (titel: string, absaetze: string[], bereiche: [string, string][], bereicheTitel: string) =>
  `# ${titel}\n\n${absaetze.join("\n\n")}\n\n## ${bereicheTitel}\n\n${bereiche.map(([b, t]) => `- **${b}**: ${t}`).join("\n")}\n`;

