const PER_IDEE = new Map(IDEEN.map((i) => [i.idee, i]));
export const ideePer = (idee: string) => PER_IDEE.get(idee);

/** Katalog mit Stand: frei, oder von welchem Projekt übernommen (Entwurf oder veröffentlicht). */
export async function ideenListe(db: Db) {
  const genommen = new Map((await db.query(
    "select idee, slug, name, entwurf from projekte where idee is not null and not gesperrt")).rows.map((r) => [r.idee as string, r]));
  return IDEEN.map((i) => {
    const p = genommen.get(i.idee);
    return { ...i, uebernommen: p ? { projekt: p.slug, name: p.name, entwurf: p.entwurf } : null };
  });
}

/** Ein Entwurf, der 14 Tage nicht veröffentlicht wurde, gibt seine Idee wieder frei. */
export async function ideenFreigeben(db: Db) {
  return (await db.query("update projekte set idee = null where idee is not null and entwurf and erstellt < now() - interval '14 days'")).rowCount ?? 0;
}
